"use strict";

/**
 * Telemetry filtering for outbound client payloads.
 *
 * Strips provider-side telemetry/analytics fields from responses before they
 * reach the client. These fields are generated by inference providers (OpenAI,
 * Groq, Fireworks, Deepseek, etc.) for their own observability and have no
 * semantic value for the IDE client. Sending them through leaks provider
 * identity and can confuse IDE telemetry collectors.
 *
 * Safety constraints:
 * - MUST NOT filter anything from request bodies (inbound from client).
 * - MUST NOT touch Copilot auth/fingerprint fields (machineId, devDeviceId,
 *   sessionId, interactionId — these are in outbound request headers to
 *   Copilot, not in provider response bodies, and are never filtered here).
 * - MUST preserve usage, choices, model, id, object, created — all fields the
 *   client uses for inference.
 */

/**
 * Top-level JSON keys in non-streaming provider responses that are pure
 * provider telemetry and carry no inference value for the client.
 *
 * Rules for inclusion:
 * - Must be a known provider-side field (not part of the OpenAI spec that
 *   clients depend on for inference).
 * - Must not be `usage`, `choices`, `model`, `id`, `object`, or `created`.
 * - Confirmed sources listed in comments.
 */
const NON_STREAMING_TELEMETRY_KEYS = new Set([
  // OpenAI: internal routing/infrastructure fingerprint — not stable across
  // calls and not used by any IDE client for anything functional.
  "system_fingerprint",

  // Groq: timing and routing metadata object {"model_id","request_id",...}
  "x_groq",

  // Fireworks AI: inference performance telemetry
  "inference_id",          // per-request inference trace ID
  "completion_tokens_per_sec", // throughput metric — only in non-streaming too
  "producer",              // routing node identifier

  // DeepSeek / some inference proxies: usage-adjacent throughput field
  "prompt_eval_count",     // raw token eval count, duplicates usage.prompt_tokens
  "eval_count",            // raw completion eval count, duplicates usage.completion_tokens
  "eval_duration",         // nanosecond timing
  "prompt_eval_duration",  // nanosecond timing
  "total_duration",        // nanosecond timing
  "load_duration",         // model load time

  // Generic OpenAI-compatible providers: service routing hints
  "service_tier",          // "default"/"scale" — internal routing hint, not inference data
]);

/**
 * Whether a streaming SSE chunk text contains provider telemetry that should
 * be suppressed entirely before forwarding to the client.
 *
 * Returns true only for whole-chunk telemetry events (chunks whose entire
 * payload is telemetry). Does not parse partial or multi-event chunks.
 *
 * @param {string} text - raw SSE chunk text
 * @returns {boolean}
 */
function isStreamingTelemetryChunk(text) {
  if (typeof text !== "string") return false;
  if (!/data:\s*\{/.test(text)) return false;
  const jsonMatch = text.match(/data:\s*(\{.+\})/);
  if (!jsonMatch) return false;
  try {
    const parsed = JSON.parse(jsonMatch[1]);
    // Existing fields from original inline filter
    if (parsed.inference_id) return true;
    if (parsed.completion_tokens_per_sec) return true;
    if (parsed.producer) return true;
    // Groq timing chunk (no choices, has x_groq)
    if (parsed.x_groq && !parsed.choices) return true;
    // DeepSeek/Ollama timing-only chunks
    if (parsed.eval_duration && !parsed.choices) return true;
    if (parsed.load_duration && !parsed.choices) return true;
  } catch {
    // malformed JSON — not a telemetry chunk, let it through
  }
  return false;
}

/**
 * Strip provider telemetry keys from a non-streaming JSON response body string.
 *
 * Parses the body, removes known telemetry keys from the top level, and
 * returns the cleaned body. If the body is not valid JSON or does not need
 * stripping, returns the original string unchanged.
 *
 * @param {string} bodyStr - raw provider response body
 * @returns {string} cleaned body (original if no stripping needed / not JSON)
 */
function stripNonStreamingTelemetryFields(bodyStr) {
  if (typeof bodyStr !== "string" || !bodyStr.trim().startsWith("{")) return bodyStr;
  let parsed;
  try {
    parsed = JSON.parse(bodyStr);
  } catch {
    return bodyStr;
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return bodyStr;

  let dirty = false;
  for (const key of NON_STREAMING_TELEMETRY_KEYS) {
    if (Object.prototype.hasOwnProperty.call(parsed, key)) {
      dirty = true;
      break;
    }
  }
  if (!dirty) return bodyStr;

  const cleaned = { ...parsed };
  for (const key of NON_STREAMING_TELEMETRY_KEYS) {
    delete cleaned[key];
  }
  try {
    return JSON.stringify(cleaned);
  } catch {
    return bodyStr;
  }
}

module.exports = {
  NON_STREAMING_TELEMETRY_KEYS,
  isStreamingTelemetryChunk,
  stripNonStreamingTelemetryFields,
};
